INSERT INTO "ProductTranslation" ("id", "productId", "language", "name", "description", "slug", "metaTitle", "metaDesc", "keywords", "ogImage", "canonical", "details", "h1") VALUES ('5d028806-a7a5-43ac-a2e3-18b5090f78d9', '99587de5-546f-408c-b026-666d9266e74b', 'ar', 'بودرة العكر الفاسي المغربية لتفتيح وتجديد البشرة', 'Natural poppy and pomegranate powder. Used for lip & cheek tint and traditional skincare treatments.', 'fassi-powder-ar', 'بودرة العكر الفاسي المغربية ', 'Moroccan Aker Fassi Powder is one of the most famous beauty secrets in Morocco. Extracted from natural flower petals, it helps lighten the skin, reduce pigmentation, and give the complexion a youthful glow. Rich in antioxidants, it is ideal for rejuvenating and brightening the skin.', 'Aker Fassi wholesale, Moroccan fassi powder, skin lightening powder, natural facial rejuvenation, fassi beauty powder', NULL, NULL, '<h1 style="text-align: right;"><strong>بودرة العكر الفاسي المغربية لتفتيح البشرة وتجديدها – 100% طبيعي</strong></h1><p>بودرة العكر الفاسي المغربي تُعد من أشهر أسرار الجمال التقليدي، وتُستخدم لتفتيح البشرة وتنقيتها. تستخرج من أزهار نبات الفاسي المجففة وتشتهر بقدرتها على منح البشرة إشراقة طبيعية.</p><h4><strong>فوائد العكر الفاسي</strong></h4><ul><li><p>تفتيح البشرة وتقليل التصبغات والبقع الداكنة</p></li><li><p>تنقية البشرة من الشوائب وتقليل حب الشباب</p></li><li><p>تجديد خلايا البشرة وتحسين مرونتها</p></li><li><p>تقليل التجاعيد والخطوط الدقيقة</p></li><li><p>يعمل كمقشر لطيف يزيل خلايا الجلد الميتة</p></li><li><p>مثالي للبشرة الحساسة</p></li><li><p>يمنح البشرة نضارة ولمعاناً طبيعياً</p></li></ul><h4><strong>طريقة الاستخدام</strong></h4><p>يُخلط مسحوق العكر الفاسي مع ماء الورد أو العسل، ثم يوضع على الوجه لمدة 20 دقيقة قبل شطفه بالماء الفاتر. يمكن استخدامه أسبوعياً للحصول على بشرة متجددة.</p><p>العكر الفاسي غني بمضادات الأكسدة، مما يجعله من أفضل العلاجات الطبيعية لمكافحة الشيخوخة واستعادة نضارة البشرة.</p><p><a target="_blank" rel="noopener noreferrer nofollow" class="floating-whatsapp" href="https://wa.me/212648273228"><br></a></p>', 'بودرة العكر الفاسي المغربية لتفتيح وتجديد البشرة');
